with open(PATH, encoding="utf-8-sig", newline="") as f:
    rd = csv.DictReader(f)
    rows = list(rd)
    cols = rd.fieldnames
filled = 0
for r in rows:
    key = (r["persona_id"], int(r["stage_id"]))
    if key in N:
        r["emotion_note"] = N[key]
        filled += 1
with open(PATH, "w", encoding="utf-8-sig", newline="") as f:
    w = csv.DictWriter(f, fieldnames=cols)
    w.writeheader()
    w.writerows(rows)
print("emotion_note заполнено:", filled, "из", len(rows))
missing = [k for k in [(p, s) for p in ["P1","P2","P3","P4","P5"] for s in range(1, 14)] if k not in N]
print("пропущено:", missing)
